namespace SatisfactoryPlanner;
static class Program {
 [STAThread] static void Main(string[] args){
  ApplicationConfiguration.Initialize();
  try {var data=GameData.Load();if(args.Contains("--selftest")){Tests.Run(data);SurplusGuidance.Test(data);return;}if(args.Contains("--settings-test")){MainForm.AppearanceFileOverride=args[Array.IndexOf(args,"--settings-test")+1];using var testForm=new MainForm(data);testForm.TestSettingsMenu();return;}if(args.Contains("--ui-test")){MainForm.AppearanceFileOverride=args[Array.IndexOf(args,"--ui-test")+1];using var testForm=new MainForm(data);testForm.TestAppearance();return;}var form=new MainForm(data);if(args.Contains("--material-test")){form.TestMaterials();return;}if(args.Contains("--map-test")){form.TestMap();return;}if(args.Contains("--window-test")){form.TestWindowRestore();return;}if(args.Any(a=>a.StartsWith("--screenshot"))){if(args.Contains("--screenshot-small")){form.Width=1180;form.Height=800;}form.Show();Application.DoEvents();if(args.Contains("--screenshot-en"))form.SetLanguage("en");if(args.Contains("--screenshot-dark"))form.SetDark(true,false);if(args.Contains("--screenshot-light"))form.SetDark(false,false);if(args.Contains("--screenshot-surplus"))form.PreviewSurplus();if(args.Contains("--screenshot-materials"))form.PreviewPage("Baukosten");if(args.Contains("--screenshot-recipes"))form.PreviewPage("Rezepte");if(args.Contains("--screenshot-map"))form.PreviewPage("Karte");if(args.Contains("--screenshot-machines"))form.PreviewPage("Maschinen");if(args.Contains("--screenshot-advanced"))form.PreviewPage("+  Rohstoff-Einstellungen");if(args.Contains("--screenshot-settings"))form.PreviewSettings();Application.DoEvents();using var bitmap=new Bitmap(form.Width,form.Height);form.DrawToBitmap(bitmap,new Rectangle(0,0,form.Width,form.Height));bitmap.Save(Path.Combine(AppContext.BaseDirectory,"Vorschau.png"));form.Close();return;}Application.Run(form);}
  catch(Exception ex){if(args.Contains("--selftest")||args.Contains("--ui-test")||args.Contains("--window-test")||args.Contains("--map-test")||args.Contains("--material-test")||args.Contains("--settings-test"))throw;MessageBox.Show(ex.Message,"Satisfactory Planer",MessageBoxButtons.OK,MessageBoxIcon.Error);}
 }
}
