 void Read(){if(target.SelectedValue is not string id)throw new InvalidOperationException("Bitte ein Produkt auswählen.");settings.Target=id;settings.Rate=(double)rate.Value;settings.Overclock=overclock.Checked;settings.Clock=(double)clock.Value;settings.Miner=miner.SelectedIndex+1;settings.Purity=new[]{.5,1d,2d}[purity.SelectedIndex];settings.WellNodes=(int)nodes.Value;}
