   surplus.Rows.Clear();foreach(var (id,v) in plan.Surplus.OrderBy(x=>data.Name(x.Key)))surplus.Rows.Add(data.Name(id),N(v),data.Unit(id),SurplusGuidance.Advice(data,id,v));if(plan.Surplus.Count==0)surplus.Rows.Add("Keine Überschüsse", "0", "",Ui.T("Alles wird in deiner Produktionskette verwendet. Keine Entsorgung nötig."));
   costs.Rows.Clear();foreach(var (id,v) in plan.Costs.OrderBy(x=>data.Name(x.Key))){bool owned=settings.OwnedMaterials.Contains(id);int index=costs.Rows.Add(data.Name(id),N(v),owned,owned?"0":N(v));costs.Rows[index].Tag=id;}
   notes.Text=$"DATENQUELLE\r\n{data.Source}\r\nSteam-Build: {data.Build}\r\n{data.Recipes.Count} Maschinenrezepte; Namen aus den Sprachdateien deiner Installation.\r\n\r\nBERECHNUNG\r\nGanze Maschinen, gleichmäßig auf den erforderlichen Takt eingestellt. Der eingestellte Maximalwert begrenzt den Takt. Rohstoffbedarf verändert sich durch Übertaktung nicht.\r\nStrom: Basisleistung × Takt^{1.321929}; variable Maschinenleistung wird als Mittelwert und Spitze ausgewiesen.\r\n\r\n"+string.Join("\r\n\r\n",plan.Notes);
   initializing=true;recipes.Rows.Clear();var recipeItems=plan.Stages.Where(s=>s.Recipe!=null).Select(s=>s.Item).Append(settings.Target).Distinct().OrderBy(data.Name);foreach(var id in recipeItems){var options=data.Options(id);if(options.Count==0)continue;int index=recipes.Rows.Add(data.Name(id));var row=recipes.Rows[index];row.Tag=id;var cell=(DataGridViewComboBoxCell)row.Cells[1];cell.DisplayMember="Name";cell.ValueMember="Id";cell.DataSource=options;cell.Value=options.FirstOrDefault(r=>r.Id==settings.Choices.GetValueOrDefault(id))?.Id??options[0].Id;}initializing=false;
   tree.BeginUpdate();tree.Nodes.Clear();var byItem=plan.Stages.Where(s=>s.Recipe!=null).ToDictionary(s=>s.Item);TreeNode Build(string id,double amount,HashSet<string> path){var node=new TreeNode($"{data.Name(id)} · {N(amount)} {data.Unit(id)}");if(path.Contains(id)){node.Nodes.Add("↻ Rückführung – in der Gesamtbilanz berücksichtigt");return node;}if(byItem.TryGetValue(id,out var stage)){var next=new HashSet<string>(path){id};node.Nodes.Add($"{stage.Building.Name}: {stage.Count} × {N(stage.Clock)} % · Gesamtbedarf dieser Stufe: {N(stage.Rate)}/min");double runs=amount/stage.Recipe!.Outputs[0].Amount;foreach(var q in stage.Recipe.Inputs)node.Nodes.Add(Build(q.Item,q.Amount*runs,next));}else node.Nodes.Add(plan.Raw.ContainsKey(id)?"Rohstoff – Förderanlage siehe Maschinen":"Nebenprodukt-Rückführung oder externer Eingang – siehe Bilanz");return node;}
   tree.Nodes.Add(Build(settings.Target,settings.Rate,[]));tree.Nodes[0].Expand();foreach(TreeNode n in tree.Nodes[0].Nodes)n.Expand();tree.EndUpdate();
   status.Text=$"{plan.Raw.Count} Rohstoffe · {plan.Surplus.Count} Überschüsse · {plan.Shards} Leistungssplitter · Stromspitze: {N(plan.Peak)} MW · Baukosten ohne Transport und Stromnetz";
   Ui.Apply(this);
  }catch(Exception ex){initializing=false;plan=null;machineMap.Clear();summary.Text="Bitte passe deine Auswahl an";machineValue.Text=powerValue.Text=rawValue.Text=surplusValue.Text="—";if(overviewResizeHandler!=null){overview.Resize-=overviewResizeHandler;overviewResizeHandler=null;}foreach(Control c in overview.Controls.Cast<Control>().ToArray())c.Dispose();overview.Controls.Clear();var error=Theme.Label("Hier erscheint dein Bauplan.\n\n"+ex.Message,12);error.Dock=DockStyle.Top;error.Height=120;overview.Controls.Add(error);status.Text=ex.Message;stages.Rows.Clear();resources.Rows.Clear();surplus.Rows.Clear();costs.Rows.Clear();tree.Nodes.Clear();Ui.Apply(this);}
 }
 void Save(){try{Read();using var dialog=new SaveFileDialog{Filter=Ui.T("Produktionsplan (*.json)|*.json"),FileName="Produktionsplan.json"};if(dialog.ShowDialog()==DialogResult.OK)File.WriteAllText(dialog.FileName,JsonSerializer.Serialize(settings,new JsonSerializerOptions{WriteIndented=true}));}catch(Exception ex){MessageBox.Show(Ui.T(ex.Message));}}
 void LoadPlan(){using var dialog=new OpenFileDialog{Filter=Ui.T("Produktionsplan (*.json)|*.json")};if(dialog.ShowDialog()!=DialogResult.OK)return;try{var s=JsonSerializer.Deserialize<Settings>(File.ReadAllText(dialog.FileName))??throw new Exception("Ungültige Plandatei.");if(!data.Items.ContainsKey(s.Target)||s.Rate<.001||s.Rate>1e7||s.Clock<100||s.Clock>250||s.Miner<1||s.Miner>3||!new[]{.5,1d,2d}.Contains(s.Purity)||s.WellNodes<1||s.WellNodes>20)throw new Exception("Der Plan enthält ungültige Einstellungen.");s.OwnedMaterials??=[];s.MapPositions??=[];s.Choices??=[];initializing=true;settings=s;search.Text="";Filter();target.SelectedValue=s.Target;rate.Value=(decimal)s.Rate;overclock.Checked=s.Overclock;clock.Enabled=s.Overclock;clock.Value=(decimal)s.Clock;miner.SelectedIndex=s.Miner-1;purity.SelectedIndex=Array.IndexOf(new[]{.5,1d,2d},s.Purity);nodes.Value=s.WellNodes;initializing=false;Calculate();}catch(Exception ex){initializing=false;MessageBox.Show(Ui.T(ex.Message));}}
 void Export(){if(plan==null)return;using var dialog=new SaveFileDialog{Filter="CSV (*.csv)|*.csv",FileName="Produktionsplan.csv"};if(dialog.ShowDialog()!=DialogResult.OK)return;try{var b=new StringBuilder();void Row(params object[] cells)=>b.AppendLine(string.Join(";",cells.Select(x=>"\""+(Ui.T(x.ToString()??"")).Replace("\"","\"\"")+"\"")));Row("Ziel",data.Name(settings.Target),N(settings.Rate),data.Unit(settings.Target));foreach(var pair in new[]{("Maschinen",stages),("Rohstoffe",resources),("Überschüsse",surplus),("Baukosten",costs)}){Row("");Row(pair.Item1);Row(pair.Item2.Columns.Cast<DataGridViewColumn>().Select(c=>(object)c.HeaderText).ToArray());foreach(DataGridViewRow r in pair.Item2.Rows)Row(r.Cells.Cast<DataGridViewCell>().Select(c=>c.Value??"").ToArray());}Row("");foreach(var note in plan.Notes)Row(Ui.T(note));File.WriteAllText(dialog.FileName,b.ToString(),new UTF8Encoding(true));}catch(Exception ex){MessageBox.Show(Ui.T(ex.Message));}}
}
















